'use strict';
const V6=require('./frozen-bot-v6'),B=require('../../baseline/core');
const IDS={P0:'v6-event-epoch12-zero-v1',raw:'v6-raw-frozen',predictive:'baseline-predictive-event12-v1',heterogeneous:'interval-complement-event12-v3',delay:'v6-event-epoch12-delay6-v1',noise:'v6-event-epoch12-jitter-miss-v1',omission:'v6-event-epoch12-forced-omission-v1'};
