const blank=()=>({requests:0,intents:0,delivered:0,missed:0,delayed:0,jittered:0,forcedMissed:0,cancelled:0,maxPending:0,ignoredNonEpoch:0,coalescedPending:0,coalescedSettlement:0,totalDelayTicks:0,pendingTicks:0});
function createAdapter(config,saved){const cfg={epoch:12,seed:0x51a72,...config};if(!Number.isInteger(cfg.epoch)||cfg.epoch<1||!Number.isInteger(cfg.delay)||cfg.delay<0||!Number.isInteger(cfg.jitter)||cfg.jitter<0||cfg.miss<0||cfg.miss>1)throw Error('Invalid event config');if(saved&&(saved.schema!=='event-adapter/1'||JSON.stringify(saved.config)!==JSON.stringify(cfg)||!Number.isInteger(saved.tick)||saved.tick<0||!Number.isInteger(saved.random)||saved.random<0||saved.random>4294967295||!Number.isInteger(saved.intents)||saved.intents<0||!saved.stats||Object.keys(blank()).some(k=>!Object.hasOwn(saved.stats,k))||saved.stats.intents!==saved.intents||saved.intents!==saved.stats.delivered+saved.stats.missed+saved.stats.cancelled+(saved.pending?1:0)||saved.stats.requests!==saved.stats.intents+saved.stats.ignoredNonEpoch+saved.stats.coalescedPending+saved.stats.coalescedSettlement||Object.values(saved.stats).some(n=>!Number.isInteger(n)||n<0)||saved.pending&&(!Number.isInteger(saved.pending.due)||saved.pending.due<saved.tick||saved.pending.index>saved.intents||typeof saved.pending.deliver!=='boolean')))throw Error('Invalid adapter checkpoint');let tick=saved?.tick||0,random=saved?.random??(cfg.seed>>>0),pending=saved?.pending||null,intents=saved?.intents||0,stats=saved?{...saved.stats}:blank();const log=[];function rng(){random=(Math.imul(random,1664525)+1013904223)>>>0;return random/4294967296;}function step(request){if(request)stats.requests++;let delivered=false,settled=false;if(pending){stats.pendingTicks++;if(pending.due<=tick){delivered=pending.deliver;if(delivered)stats.delivered++;else stats.missed++;log.push({tick,type:delivered?'deliver':'miss',index:pending.index,requestedAt:pending.at});pending=null;settled=true;}}
 if(request){if(tick%cfg.epoch!==0)stats.ignoredNonEpoch++;else if(pending)stats.coalescedPending++;else if(settled)stats.coalescedSettlement++;else{intents++;stats.intents++;const jitter=cfg.jitter?Math.floor(rng()*(cfg.jitter+1)):0,forced=intents===cfg.omitIndex,miss=forced||(cfg.miss>0&&rng()<cfg.miss),delay=cfg.delay+jitter;if(forced)stats.forcedMissed++;if(delay>0)stats.delayed++;if(jitter>0)stats.jittered++;stats.totalDelayTicks+=delay;const e={index:intents,at:tick,due:tick+delay,deliver:!miss};log.push({tick,type:'intent',index:intents,due:e.due,deliver:e.deliver});if(!delay){delivered=e.deliver;if(delivered)stats.delivered++;else stats.missed++;log.push({tick,type:delivered?'deliver':'miss',index:intents,requestedAt:tick});}else{pending=e;stats.maxPending=Math.max(stats.maxPending,1);}}}tick++;return delivered;}
 step.snapshot=()=>({schema:'event-adapter/1',config:{...cfg},tick,random,pending:pending?{...pending}:null,intents,stats:{...stats}});step.stats=()=>({...stats});step.events=()=>log;step.finish=()=>{if(pending){stats.cancelled++;log.push({tick,type:'cancel',index:pending.index});pending=null;}};return step;}
function intervalDecision(obs){const p=obs.player;let free=[[24,516]];const bodies=obs.obstacles.filter(o=>o.lethal&&!['idle','warning','cleared','expired'].includes(o.status)&&(o.bounds?.maxX??o.x+o.w)>=p.x-10&&(o.bounds?.minX??o.x)<=p.x+120).sort((a,b)=>(a.bounds?.minX??a.x)-(b.bounds?.minX??b.x));for(const o of bodies){const lo=Math.max(24,o.bounds?o.bounds.minY-24:o.y-24),hi=Math.min(516,o.bounds?o.bounds.maxY+24:o.y+o.h+24);if(hi<24||lo>516)continue;const next=[];for(const [a,b]of free){if(hi<=a||lo>=b)next.push([a,b]);else{if(lo>a)next.push([a,lo]);if(hi<b)next.push([hi,b]);}}free=next;if(!free.length)break;}const predicted=p.y+p.vy*.20;const wide=free.filter(q=>q[1]-q[0]>=44),eligible=wide.length?wide:free;const score=q=>Math.abs((q[0]+q[1])/2-predicted)+.12*Math.abs((q[0]+q[1])/2-270);eligible.sort((a,b)=>score(a)-score(b));const target=eligible.length?(eligible[0][0]+eligible[0][1])/2:270;return{action:predicted>target+4&&p.vy>-70,freeIntervals:free,target,blocked:!free.length,narrowOnly:!!free.length&&!wide.length};}
function alternative(kind){let calls=0,blocked=0,narrowOnly=0;const f=kind==='predictive'?B.act:obs=>{const q=intervalDecision(obs);calls++;blocked+=q.blocked?1:0;narrowOnly+=q.narrowOnly?1:0;return q.action;};f.snapshot=()=>({version:kind==='heterogeneous'?'interval-complement-v3':kind,calls,blocked,narrowOnly,fallback:'if no complement, flight toward270 is explicitly unqualified'});return f;}
function create(kind='P0',options={},saved){if(!IDS[kind]||saved&&(saved.kind!==kind||JSON.stringify(saved.options)!==JSON.stringify(options)))throw Error('Policy checkpoint mismatch');const base=kind==='predictive'||kind==='heterogeneous'?alternative(kind):V6.create(saved?.base);if(kind==='raw'){let stats=saved?.stats||{requests:0,delivered:0};const raw=obs=>{const a=!!base(obs);if(a){stats.requests++;stats.delivered++;}return a;};raw.snapshot=()=>({kind,options,base:base.snapshot(),stats});raw.stats=()=>stats;raw.events=()=>[];raw.finish=()=>{};return raw;}const adapter=createAdapter({...DEFAULTS[kind],seed:options.seed??0x51a72,...(kind==='omission'?{omitIndex:options.omitIndex??7}:{})},saved?.adapter);const act=obs=>adapter(!!base(obs));act.snapshot=()=>({schema:'event-policy/1',kind,options,base:base.snapshot?.()||null,adapter:adapter.snapshot()});act.stats=adapter.stats;act.events=adapter.events;act.finish=adapter.finish;return act;}
